import{bQ as l,aL as e,u as a,G as d}from"./chunks/framework.DjMJXVsR.js";const u=JSON.parse('{"title":"claude.md解密","description":"","frontmatter":{"title":"claude.md解密","date":"2026-05-25T00:00:00.000Z","categories":["AI"],"tags":["AI","ClaudeCode"]},"headers":[],"relativePath":"posts/AI/claude-code.md","filePath":"posts/AI/claude-code.md"}'),i={name:"posts/AI/claude-code.md"};function o(r,t,n,s,g,c){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="claude-md解密" tabindex="-1">claude.md解密 <a class="header-anchor" href="#claude-md解密" aria-label="Permalink to &quot;claude.md解密&quot;">​</a></h1><h2 id="一、为什么用markdown存agent记忆" tabindex="-1">一、为什么用Markdown存Agent记忆 <a class="header-anchor" href="#一、为什么用markdown存agent记忆" aria-label="Permalink to &quot;一、为什么用Markdown存Agent记忆&quot;">​</a></h2><p>MarkDown是程序员间通用的文档格式，最早OpenAI的程序员将其定为LLM的输出规范 Markdown是<strong>人+Agent都能读写</strong>的显式长期记忆，无数据库/向量引擎依赖，核心优势：</p><ol><li><strong>透明可审计</strong>：打开即看记忆内容，无黑盒</li><li><strong>持久化</strong>：存磁盘，不随进程/机器变化</li><li><strong>版本可控</strong>：Git管理，可回滚、分支、评审</li><li><strong>零迁移</strong>：标准格式，换模型/框架仅迁文件</li><li><strong>低成本</strong>：本地无额外运维与费用</li></ol><hr><h2 id="二、claude-code双轨记忆机制" tabindex="-1">二、Claude Code双轨记忆机制 <a class="header-anchor" href="#二、claude-code双轨记忆机制" aria-label="Permalink to &quot;二、Claude Code双轨记忆机制&quot;">​</a></h2><p>采用<strong>CLAUDE.md（人工）+ Auto Memory（自动）</strong> 双轨：</p><h3 id="_1-claude-md-人工编写" tabindex="-1">1. CLAUDE.md（人工编写） <a class="header-anchor" href="#_1-claude-md-人工编写" aria-label="Permalink to &quot;1. CLAUDE.md（人工编写）&quot;">​</a></h3><ul><li>定位：AI的<strong>项目入职文档</strong></li><li>官方限制：<strong>≤200行</strong>，超行降低指令遵守率</li></ul><h4 id="该写内容" tabindex="-1">该写内容 <a class="header-anchor" href="#该写内容" aria-label="Permalink to &quot;该写内容&quot;">​</a></h4><ul><li>技术栈与版本信息</li><li>常用构建/测试/启动命令（放代码块）</li><li>架构决策+背后原因</li><li>团队约定、项目特有坑点</li></ul><h4 id="不该写内容" tabindex="-1">不该写内容 <a class="header-anchor" href="#不该写内容" aria-label="Permalink to &quot;不该写内容&quot;">​</a></h4><ul><li>代码风格规则（交格式化工具）</li><li>语言/框架默认行为</li><li>大段参考文档（给链接即可）</li></ul><h4 id="高效写法技巧" tabindex="-1">高效写法技巧 <a class="header-anchor" href="#高效写法技巧" aria-label="Permalink to &quot;高效写法技巧&quot;">​</a></h4><ul><li>规则<strong>具体可验证</strong>，避免模糊表述</li><li>禁令配<strong>替代方案</strong>，不单纯禁止</li><li>慎用<code>IMPORTANT:</code>标记，避免滥用失效</li><li>用通用标题（Commands/Conventions等）</li></ul><h3 id="_2-auto-memory-自动积累" tabindex="-1">2. Auto Memory（自动积累） <a class="header-anchor" href="#_2-auto-memory-自动积累" aria-label="Permalink to &quot;2. Auto Memory（自动积累）&quot;">​</a></h3><ul><li>存储路径：<code>~/.claude/projects/&lt;project&gt;/memory/</code></li><li>入口文件：<code>MEMORY.md</code></li><li>限制：仅加载<strong>前200行/25KB</strong>，超量不读</li><li>问题：20-30会话后笔记质量可能下降</li><li>禁用：环境变量<code>CLAUDE_CODE_DISABLE_AUTO_MEMORY=1</code></li></ul><hr><h2 id="三、claude-md四层加载规则" tabindex="-1">三、CLAUDE.md四层加载规则 <a class="header-anchor" href="#三、claude-md四层加载规则" aria-label="Permalink to &quot;三、CLAUDE.md四层加载规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">层级</th><th style="text-align:left;">路径</th><th style="text-align:left;">作用范围</th><th style="text-align:left;">优先级</th></tr></thead><tbody><tr><td style="text-align:left;">组织级</td><td style="text-align:left;"><code>/etc/claude-code/CLAUDE.md</code></td><td style="text-align:left;">所有用户</td><td style="text-align:left;">最低</td></tr><tr><td style="text-align:left;">用户级</td><td style="text-align:left;"><code>~/.claude/CLAUDE.md</code></td><td style="text-align:left;">个人所有项目</td><td style="text-align:left;">中</td></tr><tr><td style="text-align:left;">项目级</td><td style="text-align:left;"><code>./CLAUDE.md</code>/<code>.claude/CLAUDE.md</code></td><td style="text-align:left;">团队共享</td><td style="text-align:left;">高</td></tr><tr><td style="text-align:left;">本地级</td><td style="text-align:left;"><code>CLAUDE.local.md</code></td><td style="text-align:left;">个人当前项目</td><td style="text-align:left;">最高</td></tr></tbody></table><ul><li>加载规则：<strong>从工作目录向上查找</strong>，近目录优先级更高</li><li>本地级：需加入<code>.gitignore</code>，不提交仓库</li></ul><hr><h2 id="四、分层管理与引用规则" tabindex="-1">四、分层管理与引用规则 <a class="header-anchor" href="#四、分层管理与引用规则" aria-label="Permalink to &quot;四、分层管理与引用规则&quot;">​</a></h2><ol><li><strong>@引用</strong><ul><li>格式：<code>@path/to/file</code>，递归≤5层</li><li>特点：<strong>启动全量加载</strong>，不减少上下文消耗</li></ul></li><li><strong>path-scoped rules</strong><ul><li>路径：<code>.claude/rules/</code></li><li>特点：<strong>按需加载</strong>，仅匹配路径时生效，适合细粒度规则</li></ul></li></ol><hr><h2 id="五、claude-md维护策略" tabindex="-1">五、CLAUDE.md维护策略 <a class="header-anchor" href="#五、claude-md维护策略" aria-label="Permalink to &quot;五、CLAUDE.md维护策略&quot;">​</a></h2><ol><li><strong>添加慢</strong>：仅当Claude犯错且规则能防错时添加</li><li><strong>删除快</strong>：无效/无影响规则立即移除</li><li><strong>错误驱动</strong>：纠错后同步更新记忆</li><li><strong>预警信号</strong><ul><li>反复道歉：规则表述问题</li><li>反复违反：文件过长，需精简</li></ul></li><li><strong>版本管理</strong>：Git提交+PR评审，可回滚</li></ol><hr><h2 id="六、markdown记忆-vs-传统记忆方案对比" tabindex="-1">六、Markdown记忆 vs 传统记忆方案对比 <a class="header-anchor" href="#六、markdown记忆-vs-传统记忆方案对比" aria-label="Permalink to &quot;六、Markdown记忆 vs 传统记忆方案对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">Markdown记忆</th><th style="text-align:left;">向量库/RAG</th><th style="text-align:left;">数据库型框架</th></tr></thead><tbody><tr><td style="text-align:left;">检索</td><td style="text-align:left;">全量注入，无检索</td><td style="text-align:left;">语义检索，高精度</td><td style="text-align:left;">混合策略</td></tr><tr><td style="text-align:left;">上下文</td><td style="text-align:left;">随文件大小增加</td><td style="text-align:left;">按需加载，高效</td><td style="text-align:left;">按需加载，高效</td></tr><tr><td style="text-align:left;">调试</td><td style="text-align:left;">极佳，直接改文件</td><td style="text-align:left;">中等，需工具</td><td style="text-align:left;">复杂</td></tr><tr><td style="text-align:left;">成本</td><td style="text-align:left;">极低</td><td style="text-align:left;">高，需运维</td><td style="text-align:left;">极高</td></tr><tr><td style="text-align:left;">版本</td><td style="text-align:left;">原生Git</td><td style="text-align:left;">需额外同步</td><td style="text-align:left;">需额外同步</td></tr><tr><td style="text-align:left;">场景</td><td style="text-align:left;">规范、偏好、踩坑</td><td style="text-align:left;">海量文本检索</td><td style="text-align:left;">复杂多源记忆</td></tr></tbody></table><hr><h2 id="七、claude-md不适合存储内容" tabindex="-1">七、CLAUDE.md不适合存储内容 <a class="header-anchor" href="#七、claude-md不适合存储内容" aria-label="Permalink to &quot;七、CLAUDE.md不适合存储内容&quot;">​</a></h2><ul><li>大段日志、完整对话</li><li>敏感密钥、Token、账号</li><li>高频运行时数据</li><li>可实时查询的动态信息</li></ul>',33)])])}const f=l(i,[["render",o]]);export{u as __pageData,f as default};
